selector_to_html = {"a[href=\"#tle-load\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.load<a class=\"headerlink\" href=\"#tle-load\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.load</span></code> loads a tensor asynchronously from GMEM. It supports asynchronously hint.</p>", "a[href=\"#remote-access\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Remote access<a class=\"headerlink\" href=\"#remote-access\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.remote</span></code> is used to obtain a handle to a tensor located on another device. This corresponds to point-to-point communication or direct memory access (e.g., RDMA/NVLink Load). It enables kernels to explicitly access data from a specific shard.</p>", "a[href=\"#memory-management\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Memory management<a class=\"headerlink\" href=\"#memory-management\" title=\"Link to this heading\">#</a></h2><p>You can use the following operations to manage the memory.</p>", "a[href=\"#tle-device-mesh\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">tle.device_mesh<a class=\"headerlink\" href=\"#tle-device-mesh\" title=\"Link to this heading\">#</a></h4><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.device_mesh</span></code> defines the topological structure of physical devices. It is the fundamental context for all distributed operations.</p>", "a[href=\"#distribution\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Distribution<a class=\"headerlink\" href=\"#distribution\" title=\"Link to this heading\">#</a></h2><p>The Triton distributed API consists of four core parts: device mesh definition, sharding specification description, synchronization, and remote access (point-to-point communication).</p>", "a[href=\"#pipe-and-stage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Pipe and stage<a class=\"headerlink\" href=\"#pipe-and-stage\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> describes an explicit dataflow edge between a producer and one or more consumers. It simultaneously records the shared-memory stage holding the logical chunk and the synchronization required to make that chunk visible to consumers, enabling CTA-level load/compute overlap and warp-specialized producer/consumer code to use a typed descriptor instead of manually writing multiple barriers.</p>", "a[href=\"#pipeline\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Pipeline<a class=\"headerlink\" href=\"#pipeline\" title=\"Link to this heading\">#</a></h2><h3>Pipe and stage<a class=\"headerlink\" href=\"#pipe-and-stage\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.pipe</span></code> describes an explicit dataflow edge between a producer and one or more consumers. It simultaneously records the shared-memory stage holding the logical chunk and the synchronization required to make that chunk visible to consumers, enabling CTA-level load/compute overlap and warp-specialized producer/consumer code to use a typed descriptor instead of manually writing multiple barriers.</p>", "a[href=\"use-tle-struct.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Struct<a class=\"headerlink\" href=\"#use-tle-struct\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Struct. TLE-Struct is available on trition_3.6.x branch.</p>", "a[href=\"#simple-example\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Simple example<a class=\"headerlink\" href=\"#simple-example\" title=\"Link to this heading\">#</a></h3><p>Automatic software pipelining can still be triggered by <code class=\"docutils literal notranslate\"><span class=\"pre\">tl.range(...,</span> <span class=\"pre\">num_stages=...)</span></code>. Explicit pipes are suited for scenarios where producer/consumer splitting needs to be visible in the program.</p>", "a[href=\"#use-tle-lite\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Use TLE-Lite<a class=\"headerlink\" href=\"#use-tle-lite\" title=\"Link to this heading\">#</a></h1><p>This section introduces how to use TLE-Lite. TLE-Lite is available on trition_3.6.x branch.</p>", "a[href=\"#device-mesh\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">device mesh<a class=\"headerlink\" href=\"#device-mesh\" title=\"Link to this heading\">#</a></h3><h4>tle.device_mesh<a class=\"headerlink\" href=\"#tle-device-mesh\" title=\"Link to this heading\">#</a></h4><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.device_mesh</span></code> defines the topological structure of physical devices. It is the fundamental context for all distributed operations.</p>", "a[href=\"#synchronization\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Synchronization<a class=\"headerlink\" href=\"#synchronization\" title=\"Link to this heading\">#</a></h3><p>In complex distributed operators\u2014such as Ring-AllReduce or pipelined execution with independent row/column communication\u2014we often need to synchronize only thread blocks within the same \u201crow\u201d or \u201ccolumn,\u201d rather than across the entire cluster. A global synchronization would introduce unnecessary waiting overhead.\nThis API supports sub-mesh synchronization, meaning that within a large physical cluster, we can define multiple logical \u201ccommunication groups\u201d and perform synchronization independently within each group.</p>", "a[href=\"#tle-extract-tile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.extract_tile<a class=\"headerlink\" href=\"#tle-extract-tile\" title=\"Link to this heading\">#</a></h3><p>Splits the input tensor into a grid of sub-tiles based on the specified sub-tile shape, and extracts the sub-tile at the given coordinates.</p><p>Supports extraction into registers and shared memory.</p>", "a[href=\"#scan-and-sort-ops\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Scan and sort Ops<a class=\"headerlink\" href=\"#scan-and-sort-ops\" title=\"Link to this heading\">#</a></h2><p>Scan and sort Ops provide partial tensor primitives such as prefix, rank, and selection, suitable for histogram-based top-k, stream compaction, and block-level sorting and bucketing scenarios.</p><p>TLE-Lite keeps these operations as high-level semantics rather than binding them to a specific hardware implementation: users describe the scan and sort intent, and the backend selects register or shared memory lowering strategies based on the hardware.</p>", "a[href=\"#payload-fields\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Payload fields<a class=\"headerlink\" href=\"#payload-fields\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tle-distributed-barrier\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">tle.distributed_barrier<a class=\"headerlink\" href=\"#tle-distributed-barrier\" title=\"Link to this heading\">#</a></h4><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.distributed_barrier</span></code> synchronize only the set of devices corresponding to the given mesh or sub-mesh.</p><p>Read from neighboring shards (ring-style exchange).</p>", "a[href=\"#producer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Producer<a class=\"headerlink\" href=\"#producer\" title=\"Link to this heading\">#</a></h3><p>The producer holds <code class=\"docutils literal notranslate\"><span class=\"pre\">pipe.writer()</span></code>. It acquires a writable stage, fills all necessary fields for the logical chunk, and then commits the chunk, making the data observable to consumers.</p>", "a[href=\"#consumer\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Consumer<a class=\"headerlink\" href=\"#consumer\" title=\"Link to this heading\">#</a></h3><p>The consumer holds <code class=\"docutils literal notranslate\"><span class=\"pre\">pipe.reader(...)</span></code>. It waits for published chunks, reads the returned slot, and releases the stage after all reads are complete.</p>", "a[href=\"#lifecycle\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Lifecycle<a class=\"headerlink\" href=\"#lifecycle\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#tle-insert-tile\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.insert_tile<a class=\"headerlink\" href=\"#tle-insert-tile\" title=\"Link to this heading\">#</a></h3><p>Splits the input tensor into a grid of sub-tiles based on the sub-tile shape, and updates the sub-tile at the specified coordinates with a new tile.</p><p>Supports updates from registers and shared memory.</p>", "a[href=\"#sharding-specification\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Sharding specification<a class=\"headerlink\" href=\"#sharding-specification\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.sharding</span></code> is used to declare the current distribution state of a tensor across a Device Mesh. The splits list describes how each dimension of the tensor is partitioned over the mesh, while the partials list indicates whether the tensor is in a partial-sum state. Any mesh axes not explicitly mentioned are treated as broadcast (replicated).</p>", "a[href=\"#tensor-slicing\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Tensor slicing<a class=\"headerlink\" href=\"#tensor-slicing\" title=\"Link to this heading\">#</a></h2><p>Splits the input tensor into a grid of sub-tiles based on the specified sub-tile shape, and extracts the sub-tile at the given coordinates.\nGPU: Supports extraction into registers and shared memory.</p>", "a[href=\"#primitives-interactive-with-local-ptr\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Primitives interactive with local_ptr<a class=\"headerlink\" href=\"#primitives-interactive-with-local-ptr\" title=\"Link to this heading\">#</a></h2><p>The following APIs are used together with <code class=\"docutils literal notranslate\"><span class=\"pre\">tle.gpu.local_ptr</span></code>. For more information, see <a class=\"reference internal\" href=\"use-tle-struct.html\"><span class=\"std std-doc\">Use TLE-Struct</span></a>.</p>", "a[href=\"#tle-cumsum\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">tle.cumsum<a class=\"headerlink\" href=\"#tle-cumsum\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">tle.cumsum(input,</span> <span class=\"pre\">axis=0,</span> <span class=\"pre\">reverse=False,</span> <span class=\"pre\">dtype=None)</span></code> computes exclusive cumulative sum and total sum along the <code class=\"docutils literal notranslate\"><span class=\"pre\">axis</span></code> dimension in one operation.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
